import { Effect, Schema, Struct } from "effect"

export const DeliveryReceipt = Schema.Struct({
  receiptId: Schema.String,
  endpoint: Schema.String,
  deliveredAt: Schema.String,
  status: Schema.Literal("accepted", "rejected")
})

export interface CompletedDelivery {
  readonly receiptId: string
  readonly endpoint: string
  readonly deliveredAt: string
  readonly status: "accepted" | "rejected"
  readonly signingSecret: string
  readonly attemptCount: number
  readonly responseBody: string
}

export const serializeDeliveryReceipt = (delivery: CompletedDelivery) =>
  Effect.gen(function*() {
    const payload = Struct.pick(
      delivery,
      "receiptId",
      "endpoint",
      "deliveredAt",
      "status"
    )

    return yield* Schema.encodeEffect(Schema.toJsonString(DeliveryReceipt))(payload)
  })
